# Compute coefficients a and b
gcd, a, b = extended_gcd(e_1, e_2)
# Adjust if negative
if b < 0:
    ct_2 = mod_inverse(ct_2, n)
    b = -b
if a < 0:
    ct_1 = mod_inverse(ct_1, n)
    a = -a
# Recover plaintext
pt = (pow(ct_1, a, n) * pow(ct_2, b, n)) % n
flag = long_to_bytes(pt)
print(flag)
